type PageViewEvent = {
  path: string
  userAgent: string
  timestamp: string
}

const ANALYTICS_ENDPOINT = process.env.ANALYTICS_ENDPOINT

export async function logPageView(event: PageViewEvent) {
  try {
    if (!ANALYTICS_ENDPOINT) {
      console.log('[analytics] page view:', event)
      return
    }

    await fetch(ANALYTICS_ENDPOINT, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(event),
    })
  } catch (error) {
    console.error('[analytics] failed to log page view:', error)
  }
}

