import { after } from 'next/server'
import { headers } from 'next/headers'
import { logPageView } from '@/app/utils'

export default async function Home() {
  // Read request data before `after` — Server Components cannot access
  // request-time APIs (like `headers`) inside the `after` callback.
  const userAgent = (await headers()).get('user-agent') || 'unknown'

  // Schedule the analytics call to run after the response is sent,
  // so it does not block the response from reaching the user.
  after(() => {
    logPageView({
      path: '/',
      userAgent,
      timestamp: new Date().toISOString(),
    })
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>This page view is being logged to our analytics service.</p>
    </main>
  )
}

